useEffect(() => {
  if (settings == null) return
  setMode(serverMode)
  setFeatures(normaliseFeatureMap(settings.ai_features))
  const cfg = settings.ai_provider_config
  const providerName =
    readProviderString(cfg, 'default', '') ||
    readProviderString(cfg, 'provider', 'ollama')
  const entry = readProviderConfigEntry(cfg, providerName) ?? cfg
  setProvider({
    provider: providerName,
    base_url: readProviderString(entry, 'base_url', ''),
    model: readProviderString(entry, 'model', ''),
    // ADR-015 §I9 — never pre-populate the key when the server's
    // mode is off. The server already redacts in that case but we
    // double-guard here to make the invariant local-state safe.
    api_key:
      serverMode === 'off'
        ? ''
        : readProviderString(entry, 'api_key', ''),
    cost_cap_cents: settings.ai_cost_cap_cents ?? 0,
    api_protocol: readProviderString(entry, 'api_protocol', 'auto'),
    embedding_model: readProviderString(entry, 'embedding_model', ''),
  })
  setRestoreDismissed(false)
  // Intentionally depend on the JSON snapshot, not the object
  // reference, to avoid infinite re-renders.
}, [aiSnapshot])

function handleModeChange(next: AiMode) {
  if (next === mode) return
  setMode(next)
  if (next === 'off') {
    // Clear in-flight selections so the UI matches the post-save
    // server state. The backend re-clears too — this is purely
    // visual feedback.
    setFeatures(normaliseFeatureMap(undefined))
  }
}

function handleRestoreConfirm() {
  if (settings?.ai_features_archived == null) return
  const restored = normaliseFeatureMap(settings.ai_features_archived)
  setFeatures(restored)
  setRestoreDismissed(true)
  // Persist immediately so the archive snapshot itself is cleared
  // server-side on the next round-trip.
  saveAi.mutate({
    ai_mode: mode,
    ai_features: restored,
  })
}

function handleRestoreDecline() {
  setRestoreDismissed(true)
}

// ── Derived state ────────────────────────────────────────────────

const showProviderSection = mode !== 'off'
const showRestorePanel =
  mode !== 'off' &&
  !restoreDismissed &&
  archiveHasRestorableEntries(settings?.ai_features_archived)

function patch(next: Partial<AIProviderDraft>) {
  onChange({ ...value, ...next })
  setValidateBanner(null)
}

async function runValidate() {
  setValidateBanner(null)
  // Build the request payload. For local mode only mode + base_url
  // matter (the validator is provider-agnostic). For cloud mode we
  // send the full configuration so the backend can build a real
  // adapter and run a bounded chat probe — omitted fields fall back
  // to the saved per-provider entry server-side, so editing one
  // field doesn't force the user to re-state the rest.
  const req: ValidateAiProviderRequest = isCloud
    ? {
        mode: 'cloud',
        provider: value.provider,
        base_url: value.base_url,
        // Only forward api_key when the user actually typed one;
        // empty string lets the backend fall back to the saved
        // (encrypted) value rather than clobbering it with "".
        ...(value.api_key.trim() === ''
          ? {}
          : { api_key: value.api_key }),
        model: value.model,
        api_protocol: value.api_protocol,
        embedding_model: value.embedding_model,
      }
    : {
        mode: 'local',
        provider: value.provider,
        base_url: value.base_url,
      }
  try {
    const result = await validate.mutateAsync(req)
    if (result.ok) {
      const okMessage = result.pinned_ip
        ? t(
            'ai.settings.validate.successPinned',
            'OK — pinned to {{ip}}',
            { ip: result.pinned_ip },
          )
        : result.probed_model
          ? t(
              'ai.settings.validate.successProbed',
              'OK — {{model}} reachable',
              { model: result.probed_model },
            )
          : t('ai.settings.validate.success', 'OK — provider reachable')
      setValidateBanner({ kind: 'ok', message: okMessage })
      return
    }
    setValidateBanner({ kind: 'fail', message: result.message })
  } catch {
    // The hook re-shapes only the backend's 422 rejection into the
    // failure variant. A malformed request (400), a 5xx from the
    // probe, or the network being unreachable rejects out of
    // mutateAsync instead. Without this catch that rejection is
    // swallowed as an unhandled promise and the user gets no
    // feedback — the button just silently re-enables. Surface a
    // generic, non-technical banner so validation always resolves
    // to a visible outcome.
    setValidateBanner({
      kind: 'fail',
      message: t(
        'ai.settings.validate.networkError',
        'Validation failed — could not reach the server. Check your connection and try again.',
      ),
    })

        {isCloud && serverMode !== 'off' && provider.cost_cap_cents > 0 && (
          <AICostCapSpendBar capCents={provider.cost_cap_cents} />
        )}
      </div>
    </div>
  </FadeIn>
)}

{showProviderSection && (
  <FadeIn delay={0.14}>
    <AIFeatureSpendPanel
      enabled={serverMode !== 'off'}
      capCents={provider.cost_cap_cents}

const formatLastCall = (timestamp: string) => {
  const date = new Date(timestamp)
  return Number.isNaN(date.getTime())
    ? '—'
    : new Intl.DateTimeFormat(i18n.language || 'en', {
        dateStyle: 'medium',
        timeStyle: 'short',
        timeZone: 'UTC',
      }).format(date)

{CATEGORIES.map(id => (
  <Button
    key={id}
    type="button"
    size="sm"
    variant={category === id ? 'primary' : 'ghost'}
    aria-pressed={category === id}
    onClick={() => setCategory(id)}
    className="min-h-9 rounded-shape-lg border border-[var(--border-default)] px-3"
  >

{t('ai.settings.featureSpend.callsTokens', '{{calls}} calls · {{input}} in / {{output}} out · last call {{last}} UTC', {
  calls: fmtInt(row.call_count),
  input: fmtInt(row.input_tokens),
  output: fmtInt(row.output_tokens),
  last: formatLastCall(row.last_call_at),
})}
